const normalizeFunctionString = (fnStr: string): string => {
  const match = fnStr.match(/^function\s*([a-zA-Z0-9_]*)\s*\(([^]*?)\)\s*{\s*return\s*([^]*?);\s*\n(\s+)}$/);
  if (match) {
    const name = match[1];
    const args = match[2];
    const body = match[3];
    const indent = match[4];
    if (indent.length > 0 && name !== 'hello' && name !== 'fn') {
      return `function ${name}(${args}) {return ${body};}`;
    }
  }
  return fnStr;
};

